Use `millis()` so your Arduino can keep doing other tasks without pausing:

```ino
const int LED_PIN = LED_BUILTIN;
unsigned long previousMillis = 0;
const unsigned long interval = 1000;
int ledState = LOW;

void setup() {
  pinMode(LED_PIN, OUTPUT);
}

void loop() {
  unsigned long currentMillis = millis();
  if (currentMillis - previousMillis >= interval) {
    previousMillis = currentMillis;
    ledState = (ledState == LOW) ? HIGH : LOW;
    digitalWrite(LED_PIN, ledState);
  }
}
```

Here is a `.py` palindrome checker that ignores case and spaces:

```python
def is_palindrome(text: str) -> bool:
    cleaned = "".join(ch.lower() for ch in text if ch.isalnum())
    return cleaned == cleaned[::-1]

if __name__ == "__main__":
    for sample in ["racecar", "hello", "Never odd or even"]:
        print(sample, "->", is_palindrome(sample))
```

Here is the classic `.ino` Blink sketch:

```ino
void setup() {
  pinMode(LED_BUILTIN, OUTPUT);
}

void loop() {
  digitalWrite(LED_BUILTIN, HIGH);
  delay(1000);
  digitalWrite(LED_BUILTIN, LOW);
  delay(1000);
}
```

Use `analogWrite()` on a PWM-capable pin (such as pin 9 on an Arduino Uno):

```ino
const int LED_PIN = 9;

void setup() {
  pinMode(LED_PIN, OUTPUT);
}

void loop() {
  for (int brightness = 0; brightness <= 255; brightness += 5) {
    analogWrite(LED_PIN, brightness);
    delay(20);
  }
  for (int brightness = 255; brightness >= 0; brightness -= 5) {
    analogWrite(LED_PIN, brightness);
    delay(20);
  }
}
```

